package ktanesolver.module.modded.regular.simonspeaks;
import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class SimonSpeaksSolverTest{@Test void transformsAllFiveAttributesAndStoresSouvenirFacts(){var words=List.of("black","blå","groen","turkisa","punainen","pourpre","gelb","fehér","grigio");var colors=List.of("black","blue","green","cyan","red","purple","yellow","white","gray");List<SimonSpeaksBubble> bs=new ArrayList<>();for(int i=0;i<9;i++)bs.add(new SimonSpeaksBubble(i+1,colors.get(i),words.get(i)));var b=new BombEntity();b.setSerialNumber("AAAAA1");var m=new ModuleEntity();var r=new SimonSpeaksSolver().solve(new RoundEntity(),b,m,new SimonSpeaksInput(bs,List.of("TL","TL","TL","TL","TL")));var o=((SolveSuccess<SimonSpeaksOutput>)r).output();assertThat(o.positions()).containsOnly("top-middle");assertThat(o.souvenirFacts()).containsExactly("top-left","shape 1","English","black","black");assertThat(m.getState()).containsKey("simonSpeaksSouvenir");}}
